const recordId = "record-structured-2";
const current = await client.items.find<Schema.SmokeArticle>(recordId, { nested: true });

if (!current.body?.en || !current.body.it) {
  throw new Error("Expected both English and Italian body values");
}

const englishText = serialize(current.body.en);
const greetingOccurrences = englishText.split("Hello reader").length - 1;
if (greetingOccurrences !== 1) {
  throw new Error(`Expected one greeting span, found ${greetingOccurrences}`);
}

let englishBody = parse(
  englishText.replace("Hello reader", "Welcome reader"),
  current.body.en,
);

let imageBlockUpdates = 0;
englishBody = mapNodes(englishBody, (node) => {
  if (isBlockWithItemOfType(Schema.SmokeImage.ID, node)) {
    imageBlockUpdates += 1;
    return {
      ...node,
      item: buildBlockRecord<Schema.SmokeImage>({
        id: node.item.id,
        caption: "Summer portrait",
      }),
    };
  }
  return node;
});

if (imageBlockUpdates !== 1) {
  throw new Error(`Expected one image block, found ${imageBlockUpdates}`);
}

englishBody.document.children.push({
  type: "paragraph",
  children: [{ type: "span", value: "See you soon." }],
});

await client.items.update<Schema.SmokeArticle>(recordId, {
  body: { ...current.body, en: englishBody },
  meta: { current_version: current.meta.current_version },
});

console.log(JSON.stringify({ updated: recordId, imageBlockUpdates }));

