const record = await client.items.find<Schema.SmokeArticle>("record-structured-2", { nested: true });
if (!record.body?.en || !record.body.it) throw new Error("Missing expected locale values");

const english = record.body.en;
const italian = record.body.it;
const first = english.document.children[0];
const block = english.document.children[1];
const last = english.document.children[english.document.children.length - 1];

if (first?.type !== "paragraph" || block?.type !== "block" || last?.type !== "paragraph") {
  throw new Error("Unexpected English document structure");
}

const greeting = first.children.find((child) => child.type === "span" && child.value === "Welcome reader");
const link = first.children.find((child) => child.type === "link");
const finalSpan = last.children.find((child) => child.type === "span");

console.log(JSON.stringify({
  title: record.title,
  untouched: record.untouched,
  localeKeys: Object.keys(record.body).sort(),
  greeting: greeting?.type === "span" ? { value: greeting.value, marks: greeting.marks ?? [] } : null,
  link: link?.type === "link" ? { url: link.url, text: link.children.map((child) => child.value).join("") } : null,
  block: {
    id: block.item.id,
    itemTypeId: block.item.__itemTypeId,
    caption: block.item.attributes.caption,
    image: block.item.attributes.image,
  },
  finalParagraph: finalSpan?.type === "span" ? finalSpan.value : null,
  italianText: serialize(italian),
  status: record.meta.status,
  publishedAt: record.meta.published_at,
}));

